from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M13','Cronologie e archivi sedimentari','Modelli età–profondità, proxy e propagazione dell’incertezza')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M13',i,b)
m.sezione_nuova('Archivio, ancore e convenzioni temporali')
p('La cronologia collega profondità e tempo',
'''Un archivio sedimentario conserva osservazioni ordinate nello spazio stratigrafico, mentre l’interpretazione temporale richiede una relazione fra profondità ed età. Il capitolo utilizza sei ancore sintetiche distribuite fra zero e 160 centimetri, con età di calendario comprese fra zero e 2200 anni BP. Un proxy simulato è disponibile ogni due centimetri. Le deviazioni standard associate alle ancore definiscono scenari didattici di sensibilità, dei quali occorre conservare la natura ipotetica quando si interpretano bande e durate derivate.''',formula=r't=t(z),\qquad z\in[0,160]\ \mathrm{cm}',figura='M13/F01',didascalia='Sei ancore sintetiche e interpolazione lineare a tratti. La profondità aumenta verso il basso.',richiamo='Il passaggio dalla profondità al tempo richiede un modello cronologico esplicito.',origine='M13:1–10')
p('L’associazione fra ancora ed evidenza stratigrafica',
'''Ogni ancora lega un’età a una profondità e a un insieme di metadati, che nelle indagini reali comprende materiale, metodo, identificativo e contesto deposizionale. Il controllo ordina le righe per profondità e verifica la coerenza delle età, mantenendo intatte le coppie. Ordinare separatamente le età altererebbe l’associazione con i livelli, cancellando l’evidenza di eventuali inversioni. La monotonicità può essere un’ipotesi geologica pertinente per una successione indisturbata, la cui validità deve essere valutata prima di imporla al modello.''',formula=r'z_{i+1}>z_i,\qquad t_{i+1}>t_i\quad\text{nel modello monotono}',tikz=d('D01',rect(.8,.7,2.3,5.6)+''.join(linea(.8,.9+[0,20,50,80,120,160][k]*.02875,2.3,.9+[0,20,50,80,120,160][k]*.02875,'Quantum')+n(4.6,.9+[0,20,50,80,120,160][k]*.02875,lab,w=4,size=11) for k,lab in enumerate(['0 cm · 0 cal BP','20 cm · 160 cal BP','50 cm · 450 cal BP','80 cm · 780 cal BP','120 cm · 1400 cal BP','160 cm · 2200 cal BP']))),richiamo='La coppia età–profondità costituisce l’unità informativa che il controllo deve preservare.',origine='M13:11–15')
p('Origine BP e rappresentazione dell’anno civile',
'''La convenzione BP fissa il presente al 1950, indipendentemente dall’anno nel quale si esegue l’analisi. Per età già espresse in anni di calendario BP, la sottrazione da 1950 produce una coordinata sulla scala degli anni astronomici. Il passaggio alle etichette a.C. e d.C. richiede attenzione all’assenza dell’anno zero nella notazione storica: l’anno astronomico zero corrisponde al primo anno avanti Cristo. Le età negative in cal BP individuerebbero invece tempi successivi al riferimento convenzionale.''',formula=r'y_{\rm astronomico}=1950-t_{\rm cal\ BP}',tikz=d('D02',a(.5,3,7,3)+linea(1,2.5,1,3.5,'Quantum')+linea(3.4,2.5,3.4,3.5,'Classical')+linea(6.1,2.5,6.1,3.5,'Classical')+n(1,1.8,'1 a.C.',size=11)+n(3.4,1.8,'1 d.C.',size=11)+n(6.1,1.8,'1950 d.C.',size=11)+n(1,4.2,'Anno 0',size=11)+n(3.4,4.2,'Anno 1',size=11)+n(6.1,4.2,'0 cal BP',size=11)+n(3.7,5.5,'Schema delle convenzioni, senza scala uniforme.',w=6.8,size=11)),richiamo='L’origine convenzionale e la notazione dell’anno devono accompagnare ogni cronologia.',fonti='IntCal20: convenzioni temporali',origine='M13:16–20')
p('Età radiocarbonica e calibrazione',
'''Un’età radiocarbonica convenzionale richiede una calibrazione per essere espressa sulla scala del calendario, poiché la relazione fra le due scale dipende dalla storia del radiocarbonio e dal contesto del campione. Una semplice sottrazione da 1950 non esegue tale operazione. Curve di calibrazione, ambiente di formazione ed eventuali effetti di riserva devono essere scelti in modo pertinente. Le sei ancore del laboratorio sono già età di calendario inventate, per cui l’esercizio affronta la costruzione della cronologia senza simulare una calibrazione radiocarbonica reale.''',destra='Una distribuzione calibrata può essere asimmetrica o multimodale. Riassumerla automaticamente mediante una media e una deviazione standard può perdere informazione utile alla costruzione del modello stratigrafico. I dati reali richiedono la conservazione del risultato di calibrazione e delle sue assunzioni.',richiamo='Calibrazione della datazione e interpolazione età–profondità sono operazioni scientifiche distinte.',fonti='Reimer et al., 2020; Heaton et al., 2020',origine='M13:11–20; approfondimento R5')
m.sezione_nuova('Interpolazione e tassi di accumulo')
p('Interpolazione lineare fra due ancore',
'''Fra due profondità adiacenti, l’interpolazione lineare combina le rispettive età con pesi determinati dalla posizione relativa. Il modello assume che il tasso apparente resti costante entro quel segmento e consente che cambi attraversando un’ancora. A 35 centimetri, posizione intermedia fra 20 e 50 centimetri, i pesi sono entrambi un mezzo e l’età risulta pari a 305 anni cal BP. Il passaggio esatto per le ancore deriva dalla definizione dell’interpolatore e non costituisce una verifica indipendente della cronologia.''',formula=r'\lambda=\frac{z-z_i}{z_{i+1}-z_i},\qquad t(z)=(1-\lambda)t_i+\lambda t_{i+1}',tikz=d('D03',a(.6,3,6.9,3)+''.join(linea(x,2.6,x,3.4,'Quantum') for x in [1,3.7,6.4])+n(1,1.8,r'20 cm\par160 anni',w=1.8,size=11)+n(3.7,1.8,r'35 cm\par305 anni',w=2,size=11)+n(6.4,1.8,r'50 cm\par450 anni',w=1.8,size=11)+n(3.7,4.5,'λ = 1/2',size=16)+n(3.7,5.6,'La posizione intermedia assegna pesi uguali.',w=6.8,size=11)),richiamo='L’interpolazione incorpora un’ipotesi sul comportamento fra le ancore.',origine='M13:21–30')
c=estratto('M13','interpolazione',"d <- read.csv('dati/cronologia_v3.csv')\nq <- c(-10,0,35,100,160,180)\na <- approx(d$profondita_cm,d$eta_cal_BP,\n xout=q,rule=1)$y\nstopifnot(abs(a[3]-305) < 1e-12,\n is.na(a[1]),is.na(a[6]))\ndata.frame(profondita_cm=q,eta_cal_BP=a)")
p('Il dominio dell’interpolazione in R',
'''La funzione approx restituisce valori entro il dominio delimitato dalle ancore, mentre rule uguale a uno rende esplicita la mancanza di una previsione esterna. Stimare l’età a 180 centimetri richiederebbe un’ipotesi aggiuntiva sul tasso oltre l’ultima ancora. Prolungare l’ultimo segmento oppure mantenere costante l’età estrema definisce due modelli differenti, che devono essere motivati separatamente. Il controllo manuale a 35 centimetri e la verifica dei valori esterni costituiscono prove semplici della coerenza dell’implementazione.''',codice=c,richiamo='Ogni estrapolazione introduce ipotesi ulteriori rispetto all’interpolazione nel dominio osservato.',fonti='R: approx',origine='M13:26–35')
p('Tasso apparente di accumulo e rapporto inverso',
'''Il rapporto fra incremento di profondità e intervallo temporale esprime un tasso apparente di accumulo, mentre il suo inverso misura anni per centimetro. Il termine apparente ricorda che spessore attuale, compattazione, erosione e lacune possono rendere il rapporto diverso da un flusso deposizionale originario. Nella successione sintetica tutti i segmenti hanno incrementi positivi. La conversione da centimetri per anno a millimetri per anno moltiplica per dieci e deve essere applicata ai valori prima di modificarne l’etichetta.''',formula=r'r_i=\frac{z_{i+1}-z_i}{t_{i+1}-t_i},\qquad\frac{\mathrm dt}{\mathrm dz}=\frac1{r_i}',figura='M13/F02',didascalia='Tassi apparenti nei cinque segmenti. L’ampiezza delle barre segue gli intervalli di profondità.',richiamo='Il tasso deve essere accompagnato dall’unità e dalle condizioni stratigrafiche della sua interpretazione.',origine='M13:21–25,36–40')
p('Media dei tassi e ponderazione temporale',
'''La media semplice dei cinque tassi assegna uguale peso a ogni segmento, benché i segmenti abbiano durate differenti. Per descrivere l’accumulo medio lungo l’intero periodo si ponderano invece i tassi per le rispettive durate; il risultato coincide con il rapporto fra spessore totale e durata complessiva. Nel caso didattico, 160 centimetri in 2200 anni corrispondono a circa 0,727 millimetri per anno. Il confronto rende esplicita la popolazione implicita nella media: segmenti equiponderati oppure tempo trascorso.''',formula=r'\overline r_{\Delta t}=\frac{\sum_i\Delta t_i r_i}{\sum_i\Delta t_i}=\frac{\sum_i\Delta z_i}{\sum_i\Delta t_i}',tikz=d('D04',rect(.6,1.2,2.1,3.7)+rect(2.3,1.2,6.8,3.7,'Quantum')+n(1.35,2.45,r'$\Delta t_1$',size=16)+n(4.55,2.45,r'$\Delta t_2$',size=16)+n(3.7,4.6,'Il tempo trascorso determina il peso.',w=6.8)+n(3.7,5.6,'Uno spessore totale, una durata totale.',w=6.8,size=11)),richiamo='La ponderazione deriva dalla domanda alla quale deve rispondere il tasso medio.',origine='M13:41–45')
m.sezione_nuova('Scenari cronologici e propagazione')
p('Perturbazioni delle ancore e modello di sensibilità',
'''Gli scenari aggiungono alle età di base perturbazioni gaussiane con deviazioni standard didattiche pari a 0, 25, 40, 55, 80 e 100 anni. Le perturbazioni delle diverse ancore sono assunte indipendenti prima dell’eventuale condizionamento alla monotonicità; la prima ancora rimane fissa. Questa costruzione quantifica la sensibilità alle ipotesi prescelte e non equivale alla stima di una cronologia bayesiana da datazioni reali. Seme e sequenza dei numeri casuali vengono conservati per rendere identico il confronto fra procedure.''',formula=r'T_i^{(b)}=t_i+\sigma_i E_i^{(b)},\qquad E_i^{(b)}\sim N(0,\,1)',tikz=d('D05',rect(.5,.7,6.9,1.9)+n(3.7,1.3,'Ancore e deviazioni standard ipotizzate',w=6,size=11)+a(3.7,2.1,3.7,2.6)+rect(.5,2.8,6.9,4,'Quantum')+n(3.7,3.4,'500 vettori di età perturbate',w=6)+a(3.7,4.2,3.7,4.7)+n(3.7,5.3,'Controllo di monotonicità per ogni vettore',w=6.5,size=11)),richiamo='La distribuzione degli scenari è definita dalle ipotesi sulle perturbazioni.',origine='M13:46–50')
c=estratto('M13','scenari',"d <- read.csv('dati/cronologia_v3.csv')\nu <- read.csv('dati/casuali_comuni_v3.csv')\nE <- matrix(u$z[1:3000],500,6,byrow=TRUE)\nA <- sweep(E,2,d$sd_scenario_anni,'*')\nA <- sweep(A,2,d$eta_cal_BP,'+')\nok <- apply(A,1,function(a)all(diff(a)>0))\nA_ok <- A[ok,,drop=FALSE]\nc(generati=nrow(A),accettati=sum(ok),\n scartati=sum(!ok))")
p('Monotonicità e identità delle ancore',
'''Il controllo esamina ogni vettore di età mantenendo l’associazione con le profondità originarie. Uno scenario non monotono viene escluso esplicitamente, mentre ordinare le età lo trasformerebbe in una configurazione diversa da quella generata. Il rifiuto condiziona la distribuzione delle perturbazioni e può introdurre dipendenza fra ancore. Con i valori e la sequenza inclusi, tutti i cinquecento scenari superano il controllo; il codice mantiene comunque la verifica, che diventa sostanziale aumentando le deviazioni standard o riducendo la separazione temporale delle ancore.''',codice=c,richiamo='Un vincolo di ordine deve essere applicato senza trasferire un’età da una profondità all’altra.',origine='M13:46–50')
p('Bande puntuali del modello età–profondità',
'''Ogni scenario accettato viene interpolato sulle medesime profondità e produce una curva cronologica completa. I quantili al 2,5%, 50% e 97,5% vengono calcolati separatamente a ogni profondità, definendo una banda puntuale degli scenari. Tale banda esprime la variabilità indotta dalle perturbazioni specificate; non possiede automaticamente una copertura frequentista certificata né una probabilità simultanea per l’intera curva. L’incertezza sulla forma fra le ancore rimane esclusa quando tutti gli scenari utilizzano la medesima interpolazione lineare.''',figura='M13/F03',didascalia='Mediana e quantili puntuali degli scenari monotoni. Le ancore di base sono indicate in viola.',richiamo='Una banda deve dichiarare quali fonti di incertezza siano state propagate e quali restino escluse.',origine='M13:46–55')
p('Distribuzione dell’età a una profondità prefissata',
'''A cento centimetri, la cronologia di base assegna 1090 anni cal BP, combinando con pesi uguali le ancore a ottanta e centoventi centimetri. La distribuzione degli scenari restituisce una mediana prossima a 1087,5 anni e quantili al 2,5% e 97,5% prossimi a 997,7 e 1186,5 anni. Le differenze fra sintesi Monte Carlo e valore di base riflettono la sequenza finita delle perturbazioni. Raddoppiare le deviazioni standard definirebbe una nuova analisi di sensibilità, della quale andrebbero riportati anche gli eventuali scenari esclusi.''',formula=r'T(100)=\tfrac12T(80)+\tfrac12T(120)',figura='M13/F04',didascalia='Età a 100 centimetri nei cinquecento scenari. La linea viola indica la cronologia di base.',richiamo='I quantili descrivono gli scenari adottati e non aggiungono nuove evidenze di datazione.',origine='M13:51–55')
p('Propagazione lineare e covarianza fra età',
'''Entro la medesima specificazione lineare, l’età a una profondità può essere scritta come combinazione delle età delle ancore. La varianza si ricava mediante i pesi di interpolazione e la matrice di covarianza delle ancore. Due profondità possono condividere una o più ancore, producendo covarianza positiva anche quando le perturbazioni delle ancore sono inizialmente indipendenti. Il condizionamento alla monotonicità può modificare la covarianza, richiedendone un aggiornamento coerente.''',formula=r'T(z)=w(z)^\top T,\qquad\operatorname{Var}[T(z)]=w(z)^\top\Sigma w(z)\\ \operatorname{Cov}[T(z_1),T(z_2)]=w(z_1)^\top\Sigma w(z_2)',tikz=d('D06',n(3.7,.7,'Ancora condivisa',w=6)+r'\fill[Quantum] (3.7,2) circle (4pt);'+a(3.3,2.3,1.7,3.6)+a(4.1,2.3,5.7,3.6)+rect(.5,3.8,3,5.1)+rect(4.4,3.8,6.9,5.1,'Quantum')+n(1.75,4.45,r'$T(z_1)$',size=16)+n(5.65,4.45,r'$T(z_2)$',size=16)+n(3.7,5.8,'Le due età ereditano una perturbazione comune.',w=6.8,size=11)),richiamo='La propagazione deve conservare la dipendenza indotta dalle ancore comuni.',origine='M13:51–55,96–100; approfondimento R5')
m.sezione_nuova('Proxy e risoluzione temporale')
p('Il proxy sulla scala della profondità',
'''Il proxy sintetico comprende ottantuno valori acquisiti idealmente a passo costante di due centimetri. Su questa scala, intervalli uguali dell’asse rappresentano spessori uguali, mentre oscillazioni e tendenze descrivono variazioni lungo la successione. La regolarità spaziale consente di riconoscere l’ordine dei campioni, ma lascia aperta la durata rappresentata da ciascun tratto. Prima di collegare un massimo o una variazione a un evento temporale occorre applicare la cronologia e valutarne la risoluzione, insieme al rumore del proxy e al supporto del campione.''',figura='M13/F05',didascalia='Ottantuno osservazioni sintetiche, separate da due centimetri. I punti conservano la posizione dei campioni originari.',richiamo='La scala della profondità descrive lo spessore dell’archivio e deve essere distinta dalla scala del tempo.',origine='M13:56–60')
p('Il medesimo proxy sulla scala del tempo',
'''La trasformazione dell’asse assegna un’età a ogni profondità, lasciando invariati i valori del proxy. Poiché i tassi apparenti cambiano fra i segmenti, intervalli uguali in profondità corrispondono a durate diverse e la densità temporale dei campioni varia. Il confronto con la figura precedente permette di riconoscere quali porzioni vengano dilatate o compresse dalla cronologia. Qualunque analisi che richieda campionamento regolare nel tempo deve quindi verificare il nuovo asse, anziché trasferire automaticamente la frequenza definita in centimetri.''',figura='M13/F06',didascalia='Gli stessi ottantuno valori dopo la conversione mediante la cronologia di base. Le distanze temporali sono irregolari.',richiamo='Trasformare l’asse modifica le distanze fra osservazioni e il significato delle procedure temporali.',origine='M13:56–60')
p('Passo di campionamento e durata effettiva',
'''La durata fra due campioni consecutivi dipende dalla pendenza locale della curva età–profondità. Nel laboratorio, il passo di due centimetri rappresenta sedici anni nel primo segmento e quaranta anni nell’ultimo. Una variazione breve può pertanto risultare diversamente risolta lungo la successione, anche se il protocollo di campionamento resta costante in profondità. L’interpolazione cronologica rende esplicita questa eterogeneità, alla quale si aggiungono incertezze delle ancore e durata integrata dal supporto fisico di ciascun campione.''',formula=r'\Delta t_i=t(z_{i+1})-t(z_i)',figura='M13/F12',didascalia='Durata fra due campioni adiacenti, rappresentata alla profondità intermedia. Il passo spaziale resta pari a due centimetri.',richiamo='La risoluzione temporale deve essere valutata localmente lungo l’archivio.',origine='M13:56–65')
p('Finestre per indice e finestre temporali',
'''Una finestra di cinque campioni copre sempre otto centimetri fra i suoi estremi, mentre la durata cambia con la cronologia. Una finestra di più o meno cento anni mantiene invece un criterio temporale e può contenere un numero diverso di campioni nelle varie porzioni della successione. La media dei punti entro la finestra attribuisce uguale peso ai campioni, mentre una media sul tempo richiederebbe pesi coerenti con gli intervalli rappresentati. Il metodo di smoothing deve quindi specificare ampiezza, unità e regola di ponderazione.''',formula=r'\mathcal W_t=\{i:|t_i-t_0|\le100\ \mathrm{anni}\}',tikz=d('D07',a(.5,2,6.9,2)+a(.5,4.2,6.9,4.2)+''.join(r'\fill[Classical] ('+str(x)+r',2) circle (2.5pt);' for x in [1,2.1,3.2,4.3,5.4])+''.join(r'\fill[Quantum] ('+str(x)+r',4.2) circle (2.5pt);' for x in [1,1.7,2.5,4.1,6.1])+n(3.7,1.1,'Passo costante in profondità',w=6.5,size=11)+n(3.7,5.2,'Tempi irregolari dopo la conversione',w=6.5,size=11)),richiamo='L’unità della finestra e i pesi stabiliscono quale variazione venga attenuata.',origine='M13:61–65')
p('Interpolazione temporale e informazione osservata',
'''Ricostruire il proxy ogni dieci anni produce 221 righe, tutte derivate dalle ottantuno misure originarie. La griglia regolare può essere utile per confronti grafici o per procedure che richiedano un asse uniforme, purché si riconoscano la dipendenza introdotta e le ipotesi dell’interpolazione. Il numero delle righe ricostruite non fornisce nuovi gradi di libertà osservativi. Se l’analisi successiva riguarda incertezza o significatività, deve conservare la provenienza dai campioni originali e la variabilità della trasformazione cronologica.''',formula=r'\widetilde y(q)=\sum_i a_i(q)y_i',destra='Un punto interpolato è una combinazione dei campioni vicini. Più punti ricostruiti possono dipendere dagli stessi valori e condividere le medesime ancore cronologiche, accumulando dipendenza su entrambi gli assi.',richiamo='La regolarizzazione della griglia temporale modifica la rappresentazione e il modello di dipendenza.',origine='M13:66–70')
m.sezione_nuova('Discontinuità e sensibilità del modello')
p('Hiatus come discontinuità della cronologia',
'''Lo scenario di hiatus aggiunge quattrocento anni alle profondità superiori a ottanta centimetri, mantenendo separata la cronologia di base. Il salto rappresenta un intervallo temporale privo di sedimentazione conservata nel modello, per il quale servirebbero evidenze stratigrafiche o cronologiche indipendenti. La figura distingue i due rami ai lati della discontinuità, evitando che una linea obliqua suggerisca accumulo attraverso l’intervallo mancante. La scelta della profondità e della durata del salto appartiene allo scenario e non viene inferita automaticamente dal proxy.''',formula=r't_H(z)=t(z)+400\,\mathbf1\{z>80\}',figura='M13/F07',didascalia='Verde: cronologia di base. Viola: scenario con hiatus; il tratteggio indica il salto a 80 centimetri.',richiamo='Una lacuna deve essere sostenuta da evidenze indipendenti e rappresentata come discontinuità esplicita.',origine='M13:71–75')
p('Inversione cronologica e diagnosi dell’incongruenza',
'''Sostituendo in una copia l’età a ottanta centimetri con trecento anni, si introduce un’inversione fra cinquanta e ottanta centimetri. Il controllo individua il segmento nel quale l’età diminuisce con la profondità, mentre la spiegazione può richiedere un esame di errore analitico, rimaneggiamento, disturbo o associazione errata. Eliminare l’ancora soltanto perché ostacola la monotonicità trasferirebbe nel risultato una scelta non documentata. Eventuali esclusioni devono conservare il dato originario, la motivazione e un confronto di sensibilità.''',formula=r'\Delta t_i\le0\quad\Rightarrow\quad\text{verifica del segmento }i',figura='M13/F08',didascalia='Una sola ancora modificata produce un tratto cronologicamente invertito. La figura conserva l’ordine delle profondità.',richiamo='Il controllo riconosce l’incongruenza, mentre la diagnosi richiede evidenze ulteriori.',origine='M13:76–80')
p('Retta globale e variabilità dei tassi locali',
'''Una regressione lineare età–profondità assume un unico rapporto medio fra le due coordinate, mentre l’interpolazione a tratti consente cambiamenti di pendenza in corrispondenza delle ancore. La retta può avere residui anche quando la successione è monotona, poiché i tassi apparenti variano. L’interpolatore attraversa invece tutte le ancore per costruzione, cosicché il suo errore di adattamento nullo non dimostra migliore previsione. La scelta deve essere confrontata con il processo deposizionale, con la qualità delle ancore e con controlli esterni o di sensibilità.''',formula=r't(z)=\beta_0+\beta_1z+\varepsilon',figura='M13/F09',didascalia='Verde: interpolazione lineare a tratti. Viola: regressione globale sulle sei ancore.',richiamo='La flessibilità della curva deve essere giustificata dal processo e dalla capacità di previsione.',origine='M13:81–85')
p('Esclusione di un’ancora interna e sensibilità locale',
'''Si elimina un’ancora interna alla volta e si stima la sua età mediante le ancore rimaste. Gli estremi vengono conservati, perché la loro esclusione richiederebbe estrapolazione. Gli scarti risultanti misurano quanto la ricostruzione locale dipenda dall’ancora omessa, senza riprodurre l’acquisizione di nuove datazioni indipendenti. Uno scarto ampio può segnalare una variazione reale del tasso, oltre a un possibile problema della misura. La verifica deve quindi orientare l’approfondimento e non diventare una regola automatica di eliminazione.''',formula=r'e_{(-i)}=\widehat t_{(-i)}(z_i)-t_i,\qquad i=2,\ldots,5',figura='M13/F10',didascalia='Scarti delle quattro ancore interne dopo l’esclusione individuale. Il segno è previsto meno osservato.',richiamo='La sensibilità a un’ancora va interpretata nel contesto della successione e del modello.',origine='M13:86–90')
m.sezione_nuova('Pendenze, durate ed eventi')
p('Derivata del proxy e cambiamento di scala',
'''La variazione del proxy per centimetro descrive il cambiamento lungo lo spessore, mentre la variazione per anno dipende anche dalla cronologia. Dove le funzioni sono derivabili e il tasso è positivo, la regola della catena collega le due derivate tramite il tasso locale di accumulo. Una conversione basata su un unico tasso medio è adeguata soltanto se la trasformazione dell’asse è coerente con tale approssimazione. Due regressioni globali sui diversi assi possono quindi restituire pendenze che non si ottengono mediante una semplice riscalatura costante.''',formula=r'\frac{\mathrm dy}{\mathrm dt}=\frac{\mathrm dy}{\mathrm dz}\frac{\mathrm dz}{\mathrm dt}=r(z)\frac{\mathrm dy}{\mathrm dz}',tikz=d('D08',rect(.4,1.3,2.9,3.4)+n(1.65,2.35,r'$\mathrm dy/\mathrm dz$',size=16)+a(3.1,2.35,4.1,2.35,'Quantum')+n(3.6,1.4,'× r(z)',size=11)+rect(4.3,1.3,6.8,3.4,'Quantum')+n(5.55,2.35,r'$\mathrm dy/\mathrm dt$',size=16)+n(3.7,4.7,'Il tasso locale collega le due unità.',w=6.7)+n(3.7,5.7,'La relazione vale nei tratti regolari della cronologia.',w=6.8,size=10.8)),richiamo='La trasformazione dell’asse cambia l’unità e l’interpretazione della variazione.',origine='M13:91–95')
p('Durata di un intervallo e covarianza condivisa',
'''La durata fra sessanta e cento centimetri si calcola sottraendo le due età all’interno dello stesso scenario. Le età condividono l’ancora a ottanta centimetri, per cui la loro covarianza entra nella varianza della differenza. Sottrarre quantili marginali costruirebbe una quantità diversa dai quantili della durata e perderebbe l’abbinamento fra scenari. Prima del condizionamento, la deviazione standard analitica è circa 48,94 anni; il codice verifica l’equivalenza delle forme matriciale ed espansa.''',formula=r'D=T_2-T_1,\quad T_1=T(60),\ T_2=T(100)\\ \operatorname{Var}(D)=\sigma_1^2+\sigma_2^2-2\sigma_{12}',destra='Nella formula, i termini quadratici indicano le varianze delle due età; il termine con indici 12 indica la loro covarianza. I pesi delle due profondità sono differenti: a 60 cm si combinano le ancore di 50 e 80 cm; a 100 cm si combinano quelle di 80 e 120 cm. La perturbazione dell’ancora condivisa entra in entrambe le età e viene parzialmente compensata nella differenza.',richiamo='Le quantità derivate da una cronologia devono conservare la struttura congiunta delle età.',origine='M13:96–100')
c=estratto('M13','durata',"d <- read.csv('dati/cronologia_v3.csv')\nu <- read.csv('dati/casuali_comuni_v3.csv')\nA <- sweep(matrix(u$z[1:3000],500,6,TRUE),\n 2,d$sd_scenario_anni,'*')\nA <- sweep(A,2,d$eta_cal_BP,'+')\nA <- A[apply(A,1,function(a)all(diff(a)>0)),]\nv <- apply(A,1,function(a)\n diff(approx(d$profondita_cm,a,\n xout=c(60,100))$y))\nquantile(v,c(.025,.5,.975))")
p('Distribuzione degli scenari di durata',
'''La cronologia di base attribuisce 530 anni all’intervallo fra sessanta e cento centimetri. Negli scenari inclusi, la mediana è circa 529,7 anni e i quantili al 2,5% e 97,5% sono circa 433,0 e 630,5 anni. Il frammento ricostruisce la differenza per ciascun vettore di ancore, preservando la dipendenza richiesta. La distribuzione descrive soltanto le perturbazioni adottate e la regola lineare, mentre un hiatus entro l’intervallo o un diverso modello di accumulo modificherebbero il significato e il valore della durata.''',codice=c,richiamo='La durata viene derivata entro ciascuno scenario prima di riassumerne la distribuzione.',origine='M13:96–100')
p('Confronto grafico delle durate ricostruite',
'''La distribuzione delle durate permette di distinguere il valore della cronologia di base dalla variabilità prodotta dalle ancore. La concentrazione degli scenari attorno a cinquecentotrenta anni riguarda l’intervallo selezionato e le deviazioni standard dichiarate. Intervalli con combinazioni diverse di ancore possono mostrare un’incertezza differente anche a parità di durata media. La lettura deve quindi collegare la forma dell’istogramma ai pesi dell’interpolazione, alla covarianza condivisa e alle fonti di variabilità che il modello ha lasciato fuori.''',figura='M13/F11',didascalia='Durata fra 60 e 100 centimetri nei cinquecento scenari; la linea viola indica i 530 anni della cronologia di base.',richiamo='L’incertezza di una durata dipende dalla collocazione delle ancore oltre che dall’ampiezza dell’intervallo.',origine='M13:96–100')
p('Collocazione del massimo osservato del proxy',
'''Il massimo numerico del proxy sintetico si trova a 160 centimetri, al bordo inferiore dell’archivio. La cronologia di base gli assegna 2200 anni cal BP, mentre lo scenario con hiatus lo colloca a 2600 anni. La differenza deriva da due assunzioni cronologiche applicate alla stessa osservazione e non documenta uno spostamento reale dell’evento. La posizione al bordo richiede inoltre prudenza nell’identificare un picco completo, poiché la serie potrebbe proseguire oltre l’intervallo campionato. Rumore, risoluzione e significato del proxy devono accompagnare l’interpretazione geologica.''',formula=r'z_{\max}=\arg\max_{z_i}y_i,\qquad t_{\max}=t(z_{\max})',tikz=d('D09',rect(.5,.8,6.9,2)+n(3.7,1.4,'Una misura: massimo a 160 cm',w=6)+a(2.1,2.2,2.1,3.1)+a(5.3,2.2,5.3,3.1,'Quantum')+rect(.5,3.3,3.5,4.9)+rect(3.9,3.3,6.9,4.9,'Quantum')+n(2,4.1,r'Base\par2200 cal BP',w=2.6,size=11)+n(5.4,4.1,r'Hiatus\par2600 cal BP',w=2.6,size=11)+n(3.7,5.7,'Due modelli cronologici della stessa osservazione.',w=6.8,size=11)),richiamo='La collocazione temporale di un evento eredita le ipotesi della cronologia e l’incertezza del proxy.',origine='M13:106–110')
m.sezione_nuova('Consegna e studio autonomo')
p('Metadati cronologici e percorso di laboratorio',
'''La consegna conserva ancore originali, unità di profondità, convenzione BP, metodo di interpolazione, dominio, scenari di incertezza e decisioni di esclusione. I laboratori N01–N07 sviluppano controlli e tassi; N08–N12 propagano gli scenari e trasformano il proxy; N13–N16 esaminano discontinuità e sensibilità; N17–N20 completano pendenze, durate ed esportazione. Per lo studio autonomo si raddoppino le deviazioni standard e si confrontino numero di scenari accettati, età a cento centimetri e durata dell’intervallo sessanta–cento centimetri, motivando le differenze osservate.''',tikz=d('D10',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'Ancore, materiali e metadati',w=6)+a(3.7,2.1,3.7,2.6)+rect(.5,2.8,6.9,4.1,'Quantum')+n(3.7,3.45,'Modello cronologico e scenari',w=6)+a(3.7,4.3,3.7,4.8)+n(3.7,5.4,'Età, durate e proxy con provenienza',w=6.7,size=11.5)),richiamo='La cronologia deve essere riproducibile come procedimento e interpretabile come insieme di ipotesi.',origine='M13:1–10,101–105')
m.salva()
